?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Refund History — WDH</title><link rel="stylesheet" href="assets/css/style.css?v=wdh-ui-v8"><link rel="stylesheet" href="assets/css/catalog.css?v=wdh-ui-v8"></head><body><?php require __DIR__.'/includes/header.php';?><main class="simple-page"><div class="breadcrumbs">Home › Client Portal › Refunds</div><div class="portal-welcome"><div><span class="eyebrow mint">REFUNDS</span><h1>Refund History</h1><p>Track your refund requests and account balance credits.</p></div></div><div class="admin-table"><?php if(!$rows):?><div class="empty">No refund requests yet.</div><?php else:foreach($rows as $r):?><div class="admin-row"><div><strong>Refund #<?=e($r['id'])?></strong><small>Order <?=e($r['order_number']??'')?> · <?=e($r['created_at'])?></small></div><strong><?=money($r['amount'],'BDT')?></strong><span><?=e(ucfirst($r['status']))?></span><small><?=e($r['reason']??'')?></small></div><?php endforeach;endif;?></div></main><?php require __DIR__.'/includes/footer.php';?></body></html>
